<?php require_once __DIR__ . '/../includes/bootstrap.php';require_login('admin');$p=database();$id=(int)($_GET['id']??$_POST['id']??0);$s=$p->prepare('SELECT * FROM courses WHERE id=?');$s->execute([$id]);$c=$s->fetch();if(!$c)exit('Course not found.');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$p->prepare('UPDATE courses SET title=?,description=?,objectives=?,skills_covered=?,difficulty=?,duration_hours=?,is_active=? WHERE id=?')->execute([posted('title'),posted('description'),posted('objectives')?:null,posted('skills')?:null,posted('difficulty'),posted('duration'),(int)$_POST['is_active'],$id]);flash('success','Course updated.');redirect('courses.php');}page_header('Edit course');?><h1>Edit course</h1><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=csrf_token()?>"><label>Title<input name="title" value="<?=e($c['title'])?>"></label><label>Difficulty<select name="difficulty"><?php foreach(['beginner','intermediate','advanced'] as $x):?><option <?=$c['difficulty']===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select></label><label>Duration<input type="number" name="duration" value="<?=e($c['duration_hours'])?>"></label><label>Active<select name="is_active"><option value="1" <?=$c['is_active']?'selected':''?>>Yes</option><option value="0" <?=$c['is_active']?'':'selected'?>>No</option></select></label><label class="full">Description<textarea name="description"><?=e($c['description'])?></textarea></label><label>Objectives<textarea name="objectives"><?=e($c['objectives'])?></textarea></label><label>Skills<textarea name="skills"><?=e($c['skills_covered'])?></textarea></label><button class="full">Save course</button></form><?php page_footer(); ?>